      "@type": "Question",
      "name": "Does WRYDECO standard shipping include uncrating or inside assembly services?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. Complimentary standard worldwide shipping covers delivery to your address and does not include uncrating, inside assembly, or positioning services unless explicitly arranged in writing. Because solid wood sculptural bookcases are heavy handcrafted pieces, we recommend having a two-person team or hiring a qualified local moving team on delivery day."
      }
    },
    {
      "@type": "Question",
      "name": "Should tall sculptural solid wood bookcases be anchored to the wall?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. While freestanding sculptural bookcases are engineered with broad, stable hardwood bases, any bookcase exceeding 70 inches in height should be secured to solid wood wall studs using concealed anti-tip hardware to ensure complete stability in homes with children or pets."
      }
    },
    {
      "@type": "Question",
      "name": "How long does it take for a handcrafted sculptural wood bookcase to be crafted and delivered?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Estimated processing and crafting takes approximately 15 to 20 business days, followed by an estimated 3 to 5 business days in transit after dispatch, for a total estimated delivery window of 18 to 25 business days. Timelines are estimates rather than guaranteed delivery dates."
      }
    },
    {
      "@type": "Question",
      "name": "Can I modify my order or cancel if I made a mistake on size or finish?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. WRYDECO provides a 6-hour Golden Window immediately after ordering during which you can cancel your order for a 100% free refund or change size, finish, and shipping details by contacting support@wrydeco.com. Once the 6-hour window closes, production begins and orders cannot be canceled."
      }
    }
  ]
